import{_ as r,o as d,c as e,a7 as a}from"./chunks/framework.Bn19FVGY.js";const o="/ruidu-docs/images/orbitcontrol/user-guide/mgr-devices-page-list.png",s="/ruidu-docs/images/orbitcontrol/user-guide/mgr-devices-dialog-register.png",n="/ruidu-docs/images/orbitcontrol/user-guide/mgr-devices-page-detail.png",m=JSON.parse('{"title":"设备管理","description":"","frontmatter":{},"headers":[],"relativePath":"orbitcontrol/user-guide/devices.md","filePath":"orbitcontrol/user-guide/devices.md"}'),i={name:"orbitcontrol/user-guide/devices.md"};function l(c,t,h,g,p,u){return d(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="设备管理" tabindex="-1">设备管理 <a class="header-anchor" href="#设备管理" aria-label="Permalink to &quot;设备管理&quot;">​</a></h1><p>「设备管理」维护设备台账：注册设备、分配站点、查看设备详情。注意与 <a href="./live-control.html">设备控制</a> 区分——设备管理面向管理员，管理设备的「档案」；设备控制面向操作员，负责实时操控。</p><h2 id="设备列表" tabindex="-1">设备列表 <a class="header-anchor" href="#设备列表" aria-label="Permalink to &quot;设备列表&quot;">​</a></h2><p><img src="'+o+'" alt=""></p><p>表格展示所有设备，支持按名称搜索、按站点筛选和分页：</p><table tabindex="0"><thead><tr><th>列</th><th>说明</th></tr></thead><tbody><tr><td>设备名称</td><td>点击进入设备详情</td></tr><tr><td>设备类型</td><td>通用飞行器 / 地面无人车 / 水面无人船 / 云台 / 智能从属设备</td></tr><tr><td>站点</td><td>所属站点（未分配显示 <code>-</code>）</td></tr><tr><td>设备序列号</td><td>设备唯一标识</td></tr><tr><td>硬件版本</td><td>设备上报的硬件版本</td></tr><tr><td>注册状态</td><td>未注册 / 已注册 / 已拒绝</td></tr></tbody></table><h2 id="添加设备" tabindex="-1">添加设备 <a class="header-anchor" href="#添加设备" aria-label="Permalink to &quot;添加设备&quot;">​</a></h2><p>点击「添加设备」打开对话框：</p><p><img src="'+s+'" alt="" class="w-1/2"></p><table tabindex="0"><thead><tr><th>字段</th><th style="text-align:center;">必填</th><th>说明</th></tr></thead><tbody><tr><td>设备序列号</td><td style="text-align:center;">✅</td><td>设备的唯一标识，印于设备机身或随附文档</td></tr><tr><td>设备类型</td><td style="text-align:center;">✅</td><td>从类型列表选择</td></tr><tr><td>设备名称</td><td style="text-align:center;"></td><td>留空则使用序列号作为名称</td></tr><tr><td>所属站点</td><td style="text-align:center;"></td><td>可以稍后分配</td></tr></tbody></table><p>设备创建时随机生成 <strong>MQTT 接入凭证</strong>（服务器、端口、用户名即设备序列号、密码），进入设备详情页（概览页签）查看，各项可一键复制。</p><p>请将凭证配置到设备端用于 MQTT 连接（详见 <a href="/ruidu-docs/orbitcontrol/tech-spec/api/mqtt_convention.html">MQTT 协议规范 · 连接认证</a>）。</p><p>设备添加后，设备端使用分配的连接信息接入平台，上线后状态变为<strong>已注册</strong>。</p><h2 id="设备详情" tabindex="-1">设备详情 <a class="header-anchor" href="#设备详情" aria-label="Permalink to &quot;设备详情&quot;">​</a></h2><p>点击设备行进入详情页，顶部可<strong>编辑设备名称</strong>，下方页签：</p><p><img src="'+n+'" alt=""></p><table tabindex="0"><thead><tr><th>页签</th><th>内容</th></tr></thead><tbody><tr><td><strong>概览</strong></td><td>设备基本信息、传感器配置、能力参数（最大速度、电池容量等）；<strong>MQTT 接入凭证</strong>（服务器、端口、用户名、密码），供设备端配置接入；<strong>重新生成凭证</strong>按钮可重置密码</td></tr><tr><td><strong>诊断</strong></td><td>设备的诊断信息，用于排查故障</td></tr><tr><td><strong>运行日志</strong></td><td>该设备的执行历史</td></tr><tr><td><strong>固件</strong></td><td>固件版本信息与升级选项</td></tr><tr><td><strong>设置</strong></td><td>设备的配置选项</td></tr></tbody></table><h3 id="重新生成凭证" tabindex="-1">重新生成凭证 <a class="header-anchor" href="#重新生成凭证" aria-label="Permalink to &quot;重新生成凭证&quot;">​</a></h3><p>概览页签的「重新生成凭证」按钮会生成新密码（需确认）。<strong>旧密码立即失效</strong>，使用旧凭证的设备会断开连接，请将新凭证重新配置到设备端。</p>',19)])])}const _=r(i,[["render",l]]);export{m as __pageData,_ as default};
